pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 length mismatch");
    assert_eq!(conds_1.len(), n, "conds_1 length mismatch");
    assert_eq!(conds_2.len(), n, "conds_2 length mismatch");

    // Ensure the output has exactly the needed length so `avgs[i]` is always valid.
    avgs.resize(n, 0);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // Problem statement guarantees at least one is true; keep a debug check.
        debug_assert!(c1 || c2, "Both conditions false at index {i}");

        avgs[i] = match (c1, c2) {
            (true, true) => {
                let sum = vals_1[i] as u128 + vals_2[i] as u128;
                (sum / 2) as u64
            }
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => unreachable!("Input guarantees at least one condition is true"),
        };
    }
}